    from scipy.optimize import least_squares
    e=df['eps'].values;T=df['T'].values;s=df['sigma'].values
    def model(p):
        a,b,q,c,ee,f,k,g,r,h=p
        x=np.exp(-q*T);y=np.exp(-r*T);E=np.exp(-k*e)
        return a+b*x+c*e+(ee+f*y)*e*E+g*y*E+h*e**2*y
    best=None
    rng=np.random.default_rng(0)
    for t in range(60):
        p0=rng.normal(size=10)
        try:
            r=least_squares(lambda p: model(p)-s,p0,max_nfev=2000)
            if best is None or r.cost<best.cost: best=r
        except Exception: pass
    p=best.x; res=s-model(p)
    print(p.round(4), np.mean(res**2)/np.var(s))
